	"push":   {},
	"in_app": {},
}

// IsAllowedChannel reports whether channel is one the service can register.
func IsAllowedChannel(channel string) bool {
	_, ok := channels[channel]
	return ok
}

// IsAllowedStatus reports whether status is one of the four published states.
func IsAllowedStatus(status string) bool {
	switch status {
	case StatusPending, StatusRetrying, StatusSucceeded, StatusFailed:
		return true
	}
	return false
}

// Published delivery statuses.
const (
	StatusPending   = "pending"
	StatusRetrying  = "retrying"
	StatusSucceeded = "succeeded"
	StatusFailed    = "failed"
)

// RecordInput is the payload submitted through the public write entry.
// RetryCount is a pointer so a missing or null value is rejected the same
// way as a non-integer value.
type RecordInput struct {
	TemplateID    string `json:"template_id"`
	Channel       string `json:"channel"`
	OccurredAt    string `json:"occurred_at"`
	Status        string `json:"status"`
	RetryCount    *int   `json:"retry_count"`
	FailureReason string `json:"failure_reason"`
}

// Record is a successfully registered delivery attempt. Every attempt is an
// independent row; repeated notifications never overwrite earlier records.
type Record struct {
	ID            string    `json:"id"`
	TemplateID    string    `json:"template_id"`
	Channel       string    `json:"channel"`
	OccurredAt    time.Time `json:"occurred_at"`
	Status        string    `json:"status"`
	RetryCount    int       `json:"retry_count"`
	FailureReason string    `json:"failure_reason"`
}

// NewRecord validates input and builds the record as it will be stored. The id
// is assigned by the storage layer when the insert actually succeeds.
func NewRecord(in RecordInput) (Record, error) {
	templateID := strings.TrimSpace(in.TemplateID)
	if templateID == "" {
		return Record{}, ErrInvalidRecord
	}
	if !IsAllowedChannel(strings.TrimSpace(in.Channel)) || in.Channel != strings.TrimSpace(in.Channel) {
		return Record{}, ErrInvalidRecord
	}
	occurredAt, err := time.Parse(time.RFC3339, in.OccurredAt)
	if err != nil {
		return Record{}, ErrInvalidRecord
	}
	if !IsAllowedStatus(in.Status) {
		return Record{}, ErrInvalidRecord
	}
	if in.RetryCount == nil || *in.RetryCount < 0 {
		return Record{}, ErrInvalidRecord
	}
	switch in.Status {
	case StatusFailed, StatusRetrying:
		if strings.TrimSpace(in.FailureReason) == "" {
			return Record{}, ErrInvalidRecord
		}
	case StatusPending, StatusSucceeded:
		if in.FailureReason != "" {
			return Record{}, ErrInvalidRecord
		}
	}
	return Record{
		TemplateID:    templateID,
		Channel:       in.Channel,
		OccurredAt:    occurredAt.UTC(),
		Status:        in.Status,
		RetryCount:    *in.RetryCount,
		FailureReason: in.FailureReason,
	}, nil
}

// Query is a validated channel plus half-open time range query.
type Query struct {
	Channel string
	Start   time.Time
	End     time.Time
}

// NewQuery validates the query parameters. The range is [start, end), so start
// must be strictly before end.
func NewQuery(channel, startRaw, endRaw string) (Query, error) {
	if !IsAllowedChannel(strings.TrimSpace(channel)) || channel != strings.TrimSpace(channel) {
		return Query{}, ErrInvalidQuery
	}
	start, err := time.Parse(time.RFC3339, startRaw)
	if err != nil {
		return Query{}, ErrInvalidQuery
	}
	end, err := time.Parse(time.RFC3339, endRaw)
	if err != nil {
		return Query{}, ErrInvalidQuery
	}
	if !start.Before(end) {
		return Query{}, ErrInvalidQuery
	}
	return Query{
		Channel: channel,
		Start:   start.UTC(),
		End:     end.UTC(),
	}, nil
}
package api

import (
	"encoding/json"
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/notification-service/internal/delivery"
	"github.com/luwa07832/notification-service/internal/store"
)

const (
	codeInvalidRecord = "INVALID_DELIVERY_RECORD"
	codeInvalidQuery  = "INVALID_DELIVERY_QUERY"
	codeRecordMissing = "DELIVERY_RECORD_NOT_FOUND"
	codeStorageDown   = "STORAGE_UNAVAILABLE"
)

func respondError(c *gin.Context, status int, code, message string) {
	c.JSON(status, gin.H{"error": gin.H{"code": code, "message": message}})
}

// createDeliveryRecord handles POST /api/v1/delivery-records. It validates the
// submitted attempt, registers it once, and returns the stored record.
func createDeliveryRecord(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		var input delivery.RecordInput
		decoder := json.NewDecoder(c.Request.Body)
		if err := decoder.Decode(&input); err != nil {
			respondError(c, http.StatusBadRequest, codeInvalidRecord, "delivery record payload is not valid")
			return
		}

		record, err := delivery.NewRecord(input)
		if err != nil {
			respondError(c, http.StatusBadRequest, codeInvalidRecord, "delivery record payload is not valid")
			return
		}

		saved, err := st.CreateDeliveryRecord(c.Request.Context(), record)
		if err != nil {
			respondError(c, http.StatusServiceUnavailable, codeStorageDown, "delivery record storage is not available")
			return
		}
		c.JSON(http.StatusCreated, saved)
	}
}

// getDeliveryRecord handles GET /api/v1/delivery-records/:id.
func getDeliveryRecord(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		record, ok, err := st.GetDeliveryRecord(c.Request.Context(), c.Param("id"))
		if err != nil {
			respondError(c, http.StatusServiceUnavailable, codeStorageDown, "delivery record storage is not available")
			return
		}
		if !ok {
			respondError(c, http.StatusNotFound, codeRecordMissing, "delivery record was not found")
			return
		}
		c.JSON(http.StatusOK, record)
	}
}

// listDeliveryRecords handles GET /api/v1/delivery-records?channel=&start=&end=.
// The time range is half-open: start <= occurred_at < end.
func listDeliveryRecords(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		query, err := delivery.NewQuery(
			c.Query("channel"),
			c.Query("start"),
			c.Query("end"),
		)
		if err != nil {
			respondError(c, http.StatusBadRequest, codeInvalidQuery, "delivery query parameters are not valid")
			return
		}

		records, err := st.ListDeliveryRecords(c.Request.Context(), query)
		if err != nil {
			respondError(c, http.StatusServiceUnavailable, codeStorageDown, "delivery record storage is not available")
			return
		}
		if records == nil {
			records = []delivery.Record{}
		}
		c.JSON(http.StatusOK, gin.H{"records": records})
	}
}
package api

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/notification-service/internal/store"
)

// NewRouter wires the public HTTP surface. The README describes the error shape
// every entry must keep.
func NewRouter(st *store.Store) *gin.Engine {
	gin.SetMode(gin.ReleaseMode)
	router := gin.New()
	router.Use(gin.Recovery())

	router.GET("/healthz", func(c *gin.Context) {
		if err := st.Ping(); err != nil {
			c.JSON(http.StatusServiceUnavailable, gin.H{"error": gin.H{"code": "storage_unavailable", "message": "database is not available"}})
			return
		}
		c.JSON(http.StatusOK, gin.H{"status": "ok", "database": "ok"})
	})

	deliveryRecords := "/api/v1/delivery-records"
	router.POST(deliveryRecords, createDeliveryRecord(st))
	router.GET(deliveryRecords, listDeliveryRecords(st))
	router.GET(deliveryRecords+"/search", searchDeliveryRecords(st))
	router.GET(deliveryRecords+"/failure-summary", failureSummary(st))
	router.GET(deliveryRecords+"/attempt-overview", attemptOverview(st))
	router.GET(deliveryRecords+"/trend", deliveryTrend(st))
	router.GET(deliveryRecords+"/channel-comparison", channelComparison(st))
	router.GET(deliveryRecords+"/:id", getDeliveryRecord(st))

	router.NoRoute(func(c *gin.Context) {
		c.JSON(http.StatusNotFound, gin.H{"error": gin.H{"code": "route_not_found", "message": "no route matches this path"}})
	})
	return router
}

