var ErrInvalidSummary = errors.New("invalid delivery failure summary")

// SummaryInput carries the raw failure-summary parameters as received on the
// query string. The pointer field distinguishes an omitted template_id from an
// empty one: a present but blank value is invalid, while nil means the filter
// is unused.
type SummaryInput struct {
	Channel    string
	Start      string
	End        string
	TemplateID *string
}

// SummaryQuery is the validated failure-summary query. It shares the channel
// and half-open [Start, End) semantics with the basic list query and adds an
// optional exact template identifier filter.
type SummaryQuery struct {
	Channel    string
	Start      time.Time
	End        time.Time
	TemplateID *string
}

// FailureGroup counts the attempts whose stored failure reason matches one
// exact, unnormalized piece of text.
type FailureGroup struct {
	FailureReason string `json:"failure_reason"`
	AttemptCount  int    `json:"attempt_count"`
}

// NewSummary validates the failure-summary parameters. Only failed or retrying
// records with a non-empty failure reason can ever be counted; the storage
// layer enforces that part of the contract.
func NewSummary(in SummaryInput) (SummaryQuery, error) {
	if !IsAllowedChannel(strings.TrimSpace(in.Channel)) || in.Channel != strings.TrimSpace(in.Channel) {
		return SummaryQuery{}, ErrInvalidSummary
	}
	start, err := time.Parse(time.RFC3339, in.Start)
	if err != nil {
		return SummaryQuery{}, ErrInvalidSummary
	}
	end, err := time.Parse(time.RFC3339, in.End)
	if err != nil {
		return SummaryQuery{}, ErrInvalidSummary
	}
	if !start.Before(end) {
		return SummaryQuery{}, ErrInvalidSummary
	}
	query := SummaryQuery{
		Channel: in.Channel,
		Start:   start.UTC(),
		End:     end.UTC(),
	}
	if in.TemplateID != nil {
		templateID := strings.TrimSpace(*in.TemplateID)
		if templateID == "" {
			return SummaryQuery{}, ErrInvalidSummary
		}
		query.TemplateID = &templateID
	}
	return query, nil
}
package store

import (
	"context"
	"fmt"
	"strings"

	"github.com/luwa07832/notification-service/internal/delivery"
)

// FailureSummary groups failed or retrying attempts by their exact, stored
// failure reason. TotalAttempts is the sum of the per-group counts.
type FailureSummary struct {
	Groups        []delivery.FailureGroup
	TotalAttempts int
}

// FailureSummary returns read-only failure-reason counts for records matching
// the validated query. Only failed or retrying records with a non-empty
// stored failure reason participate, and the stored text is grouped verbatim:
// no case folding, trimming or other normalization is applied. Groups are
// ordered by attempt count descending and then by the original failure reason
// ascending. Registration and stored history are never modified.
func (s *Store) FailureSummary(ctx context.Context, query delivery.SummaryQuery) (FailureSummary, error) {
	clauses := []string{
		"channel = ?",
		"occurred_at >= ?",
		"occurred_at < ?",
		"status IN (?, ?)",
		"failure_reason <> ''",
	}
	args := []any{
		query.Channel,
		query.Start.UTC().Format(storedTimeFormat),
		query.End.UTC().Format(storedTimeFormat),
		delivery.StatusFailed,
		delivery.StatusRetrying,
	}
	if query.TemplateID != nil {
		clauses = append(clauses, "template_id = ?")
		args = append(args, *query.TemplateID)
	}

	rows, err := s.db.QueryContext(ctx,
		`SELECT failure_reason, COUNT(*)
		   FROM delivery_records
		  WHERE `+strings.Join(clauses, " AND ")+`
		  GROUP BY failure_reason
		  ORDER BY COUNT(*) DESC, failure_reason ASC`,
		args...,
	)
	if err != nil {
		return FailureSummary{}, fmt.Errorf("%w: %v", ErrStorageUnavailable, err)
	}
	defer rows.Close()

	groups := []delivery.FailureGroup{}
	total := 0
	for rows.Next() {
		var group delivery.FailureGroup
		if err := rows.Scan(&group.FailureReason, &group.AttemptCount); err != nil {
			return FailureSummary{}, fmt.Errorf("%w: %v", ErrStorageUnavailable, err)
		}
		groups = append(groups, group)
		total += group.AttemptCount
	}
	if err := rows.Err(); err != nil {
		return FailureSummary{}, fmt.Errorf("%w: %v", ErrStorageUnavailable, err)
	}
	return FailureSummary{Groups: groups, TotalAttempts: total}, nil
}

