func New(in Input) (Template, error) {
	templateID := strings.TrimSpace(in.TemplateID)
	if templateID == "" {
		return Template{}, ErrInvalidTemplate
	}
	name := strings.TrimSpace(in.Name)
	if name == "" {
		return Template{}, ErrInvalidTemplate
	}
	if strings.TrimSpace(in.Body) == "" {
		return Template{}, ErrInvalidTemplate
	}
	channels, ok := normalizeChannels(in.Channels)
	if !ok {
		return Template{}, ErrInvalidTemplate
	}
	if in.Enabled == nil {
		return Template{}, ErrInvalidTemplate
	}
	return Template{
		TemplateID: templateID,
		Name:       name,
		Body:       in.Body,
		Channels:   channels,
		Enabled:    *in.Enabled,
	}, nil
}

// normalizeChannels accepts exactly one to four distinct known channels. Each
// token is trimmed; the returned slice keeps the request order.
func normalizeChannels(raw []string) ([]string, bool) {
	if len(raw) < MinChannels || len(raw) > MaxChannels {
		return nil, false
	}
	seen := make(map[string]struct{}, len(raw))
	channels := make([]string, 0, len(raw))
	for _, entry := range raw {
		channel := strings.TrimSpace(entry)
		if !delivery.IsAllowedChannel(channel) {
			return nil, false
		}
		if _, dup := seen[channel]; dup {
			return nil, false
		}

